/* Cognicopia license service, one file for Cloudflare Workers. Generated by license-service/build-worker.mjs from license-service/src/*.mjs: change those, not this. */

/* ---------- token.mjs ---------- */

/* =====================================================================
   Signed license keys, made with the Web Crypto API (so the same file runs
   on Netlify, Cloudflare Workers, Vercel and Node, with nothing to install).

   A key is  COG1.<payload>.<signature>:
     payload    base64url of a small JSON object { v, f, t, e, i, n }
                (version, facility name, tier, paid-through date, issued date, license id)
     signature  base64url of the 64 bytes r||s: ECDSA P-256 over SHA-256 of the text "COG1.<payload>"

   It is the format scripts/issue-license.mjs and license-desk.html write by hand, and the browser
   checks it against the public key in src/config/license.js with no server
   (assets/services/licenseManager.js). A key holds a business name and two dates. It never holds a
   resident's name or any health detail.
   ===================================================================== */
const LICENSE_TIERS = ["monthly_facility", "annual_facility", "enterprise"];

const enc = new TextEncoder();

function b64u(bytes) {
  const b = new Uint8Array(bytes);
  let s = "";
  for (let i = 0; i < b.length; i++) s += String.fromCharCode(b[i]);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

/** Tidy a name from a checkout form: no control characters or angle brackets, single spaces, at most 120 characters. */
function cleanFacilityName(raw) {
  return String(raw ?? "").replace(/[\u0000-\u001f\u007f<>]/g, " ").replace(/\s+/g, " ").trim().slice(0, 120);
}

/** The private key as a host setting can hold it: a PEM with real line breaks, a PEM on one line with \n, or bare base64. */
function derOfKey(text) {
  const body = String(text ?? "").replace(/\\n/g, "\n").replace(/-----[^-]+-----/g, "").replace(/\s+/g, "");
  if (!/^[A-Za-z0-9+/=]{60,}$/.test(body)) throw new Error("The signing key setting is not a private key.");
  const bin = atob(body);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out.buffer;
}

async function importSigningKey(text) {
  return crypto.subtle.importKey("pkcs8", derOfKey(text), { name: "ECDSA", namedCurve: "P-256" }, false, ["sign"]);
}

function randomId() {
  const b = crypto.getRandomValues(new Uint8Array(8));
  return "lic_" + Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
}

/** A license id that is the same for the same purchase every time, so withdrawing it withdraws every renewal too. */
async function stableId(seed) {
  const h = new Uint8Array(await crypto.subtle.digest("SHA-256", enc.encode(String(seed))));
  return "lic_" + Array.from(h.slice(0, 8), (x) => x.toString(16).padStart(2, "0")).join("");
}

async function signLicense(input, keyText) {
  const facility = cleanFacilityName(input.facility);
  if (!facility) throw new Error("A license needs a facility name.");
  if (!LICENSE_TIERS.includes(input.tier)) throw new Error("Unknown license tier.");
  if (!/^\d{4}-\d\d-\d\d$/.test(input.until) || Number.isNaN(Date.parse(input.until))) throw new Error("The paid-through date must look like 2027-10-31.");
  const payload = { v: 1, f: facility, t: input.tier, e: input.until, i: input.issued ?? new Date().toISOString().slice(0, 10), n: input.id ?? randomId() };
  const body = b64u(enc.encode(JSON.stringify(payload)));
  const key = await importSigningKey(keyText);
  const signature = await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, enc.encode("COG1." + body));
  return { token: `COG1.${body}.${b64u(signature)}`, payload };
}

/* ---------- stripe.mjs ---------- */

/* =====================================================================
   The two things this service needs from Stripe, with no library:
     - read one checkout session (a plain HTTPS request with a read-only key)
     - check that a webhook really came from Stripe (an HMAC of the body)
   ===================================================================== */
const stripeEnc = new TextEncoder();

function hexToBytes(hex) {
  if (!/^[0-9a-f]+$/i.test(hex) || hex.length % 2) return null;
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return out;
}

/**
 * Stripe-Signature looks like  t=1700000000,v1=<hex>,v1=<hex>.  The signed text is  "<t>.<raw body>"  with
 * HMAC-SHA256 under the endpoint's signing secret (whsec_...). A body older than `tolerance` seconds is refused,
 * so a captured request cannot be replayed later. Returns true or false; never throws.
 */
async function verifyStripeSignature(rawBody, header, secret, { now = Date.now(), tolerance = 300 } = {}) {
  try {
    if (!header || !secret) return false;
    const parts = String(header).split(",").map((p) => p.trim().split("="));
    const t = parts.find(([k]) => k === "t")?.[1];
    const sigs = parts.filter(([k]) => k === "v1").map(([, v]) => v);
    if (!t || !/^\d+$/.test(t) || sigs.length === 0) return false;
    if (Math.abs(now / 1000 - Number(t)) > tolerance) return false;
    const key = await crypto.subtle.importKey("raw", stripeEnc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["verify"]);
    for (const hex of sigs) {
      const bytes = hexToBytes(hex);
      if (bytes && (await crypto.subtle.verify("HMAC", key, bytes, stripeEnc.encode(`${t}.${rawBody}`)))) return true;   // verify() compares in constant time
    }
    return false;
  } catch {
    return false;
  }
}

/** Read one checkout session, with its subscription and line items. `fetchImpl` is injectable for tests. */
async function retrieveCheckoutSession(id, apiKey, fetchImpl = fetch, base = "https://api.stripe.com") {
  const url = `${base}/v1/checkout/sessions/${encodeURIComponent(id)}?expand[]=subscription&expand[]=line_items`;
  const res = await fetchImpl(url, { headers: { Authorization: `Bearer ${apiKey}` } });
  let body = null;
  try { body = await res.json(); } catch { /* an empty or non-JSON answer is handled below */ }
  if (res.status === 404 || body?.error?.code === "resource_missing") { const e = new Error("No payment was found for that reference."); e.status = 404; e.code = "not_found"; throw e; }
  if (!res.ok || !body) { const e = new Error("Stripe could not be reached."); e.status = 502; e.code = "stripe_unavailable"; throw e; }
  return body;
}

/* ---------- redeem.mjs ---------- */

/* =====================================================================
   Turn a paid Stripe Checkout into a license key.

   Nothing the browser says is trusted: this asks Stripe what the session is, and only a completed, paid
   session for one of OUR two prices becomes a key. The same reference can be redeemed again later: that is
   how a monthly license is renewed. A subscription that is still current gets a key good through its
   present period; a cancelled one gets the end of the period it paid for, so nothing is owed back and
   nothing is cut short.
   ===================================================================== */


const CHECKOUT_REFERENCE = /^cs_(?:live|test)_[A-Za-z0-9]{8,200}$/;

const DAY = 86_400_000;
const isoDay = (ms) => new Date(ms).toISOString().slice(0, 10);
/** A subscription in one of these states has paid for the period it is in. */
const PAID_STATES = new Set(["active", "trialing", "past_due", "canceled"]);

class ServiceError extends Error {
  constructor(status, code, message) { super(message); this.status = status; this.code = code; }
}

/** The end of the period a subscription has paid for, in either shape Stripe has used for it. */
function paidThrough(sub) {
  const ends = [sub.current_period_end, ...(sub.items?.data ?? []).map((i) => i.current_period_end)].filter((e) => typeof e === "number");
  return ends.length ? Math.max(...ends) : null;
}

/** deps: { stripeKey, signingKey, prices: { monthly, annual }, fetch?, now? } */
async function redeemCheckout(deps, reference) {
  if (!CHECKOUT_REFERENCE.test(reference)) throw new ServiceError(400, "invalid_request", "That is not a checkout reference.");
  const session = await retrieveCheckoutSession(reference, deps.stripeKey, deps.fetch);
  return licenseFromSession(deps, session);
}

/** The same step, for a session already in hand (the webhook re-reads it from Stripe first). */
async function licenseFromSession(deps, session) {
  if (session.status !== "complete" || !(session.payment_status === "paid" || session.payment_status === "no_payment_required")) {
    throw new ServiceError(402, "not_paid", "That payment is not finished yet.");
  }
  const sub = session.subscription && typeof session.subscription === "object" ? session.subscription : null;
  const priceId = session.line_items?.data?.[0]?.price?.id ?? sub?.items?.data?.[0]?.price?.id;
  const tier = priceId && priceId === deps.prices.monthly ? "monthly_facility" : priceId && priceId === deps.prices.annual ? "annual_facility" : null;
  if (!tier) throw new ServiceError(422, "not_a_license", "That payment is not for a Cognicopia license.");

  const now = (deps.now ?? (() => new Date()))().getTime();
  let until;
  let stable;
  if (sub) {
    if (!PAID_STATES.has(sub.status)) throw new ServiceError(402, "not_paid", "That subscription is not active.");
    const end = paidThrough(sub);
    if (end === null) throw new ServiceError(502, "stripe_incomplete", "Stripe did not say when the subscription is paid through.");
    until = isoDay(end * 1000);
    stable = sub.id;
  } else if (session.mode === "payment" && tier === "annual_facility") {
    until = isoDay((session.created ?? now / 1000) * 1000 + 365 * DAY);   // a one-time yearly payment: a year from the day it was made
    stable = session.id;
  } else {
    throw new ServiceError(422, "not_a_license", "That payment is not for a Cognicopia license.");
  }

  const named = session.collected_information?.business_name
    || session.custom_fields?.find((f) => f.key === "facility_name" || f.key === "facilityname")?.text?.value
    || session.customer_details?.business_name
    || session.customer_details?.name
    || "";
  const facilityName = cleanFacilityName(named) || "Your facility";
  const id = await stableId(stable);
  const { token } = await signLicense({ facility: facilityName, tier, until, issued: isoDay(now), id }, deps.signingKey);
  return { licenseKey: token, facilityName, tier, expiresAt: until, licenseId: id };
}

/* ---------- email.mjs ---------- */

/* =====================================================================
   The email that carries a license key to the address the buyer gave at
   checkout. Sent through Resend's HTTP API (nothing to install): the
   sender lives in one function, sendEmail, so another provider is a small
   change. The key is in the body of this one message and nowhere else:
   it is never written to a log and never returned by the webhook.
   ===================================================================== */
const TIER_NAME = { monthly_facility: "monthly facility license", annual_facility: "annual facility license", enterprise: "enterprise license" };

const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const dateText = (iso) => { const d = new Date(iso + "T12:00:00Z"); return Number.isNaN(d.getTime()) ? iso : d.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" }); };

/** The message: plain text first (what every mail program shows), and a simple HTML copy. */
function licenseEmail({ licenseKey, facilityName, tier, expiresAt, siteUrl }) {
  const plan = TIER_NAME[tier] || "facility license";
  const link = `${siteUrl.replace(/\/+$/, "")}/activate.html#license_key=${licenseKey}`;
  const through = dateText(expiresAt);
  const subject = `Your Cognicopia license key for ${facilityName}`;
  const text = [
    "Thank you for choosing Cognicopia.",
    "",
    `Your ${plan} for ${facilityName} is paid through ${through}.`,
    "",
    "YOUR LICENSE KEY",
    licenseKey,
    "",
    "To turn it on: open Cognicopia on any computer in your building, choose \"License Key / Promo\" at the top of the page, paste the key, and choose Activate Access.",
    "Or open this link on that computer and it turns on by itself:",
    link,
    "",
    "The key is checked on the computer itself, so it works with no internet and keeps working after a restart. Use it on every computer in your building.",
    "",
    "Please keep this email. Stripe also sends your payment receipt separately.",
    "",
    "Questions? Reply to this email or write to cognicopia@outlook.com.",
    "Cognicopia, made by BarronCrafts.",
  ].join("\n");
  const html = `<!doctype html><html lang="en"><body style="margin:0;padding:24px;background:#f6f3ec;color:#10241a;font:17px/1.55 Arial,Helvetica,sans-serif">
<div style="max-width:620px;margin:0 auto;background:#ffffff;border-radius:12px;padding:28px">
<h1 style="margin:0 0 12px;font-size:24px">Thank you for choosing Cognicopia</h1>
<p>Your ${esc(plan)} for <b>${esc(facilityName)}</b> is paid through <b>${esc(through)}</b>.</p>
<p style="margin:20px 0 6px"><b>Your license key</b></p>
<p style="margin:0;padding:14px;background:#eef6f0;border:1px solid #b7e4c7;border-radius:8px;font:14px/1.4 Consolas,Menlo,monospace;word-break:break-all">${esc(licenseKey)}</p>
<p style="margin-top:20px">To turn it on: open Cognicopia on any computer in your building, choose <b>License Key / Promo</b> at the top of the page, paste the key, and choose <b>Activate Access</b>.</p>
<p><a href="${esc(link)}" style="display:inline-block;padding:14px 22px;background:#1b4332;color:#ffffff;text-decoration:none;border-radius:8px;font-weight:bold">Or press here to turn it on</a></p>
<p>The key is checked on the computer itself, so it works with no internet and keeps working after a restart. Use it on every computer in your building.</p>
<p>Please keep this email. Stripe also sends your payment receipt separately.</p>
<p style="color:#4a5a52;font-size:15px">Questions? Reply to this email or write to cognicopia@outlook.com.<br>Cognicopia, made by BarronCrafts.</p>
</div></body></html>`;
  return { subject, text, html };
}

/** Send one email through Resend. A failure throws, so the webhook answers with an error and Stripe tries again later. */
async function sendEmail({ apiKey, from, replyTo, to, subject, text, html, idempotencyKey }, fetchImpl = fetch, base = "https://api.resend.com") {
  const res = await fetchImpl(`${base}/emails`, {
    method: "POST",
    headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json", ...(idempotencyKey ? { "Idempotency-Key": idempotencyKey } : {}) },
    body: JSON.stringify({ from, to: [to], subject, text, html, ...(replyTo ? { reply_to: replyTo } : {}) }),
  });
  if (!res.ok) {
    const e = new Error(`The email service answered ${res.status}.`);
    e.status = 502; e.code = "email_failed";
    throw e;
  }
}

/* ---------- handlers.mjs ---------- */

/* =====================================================================
   The three web addresses this service answers, written against the
   standard Request and Response so the same code runs on Netlify,
   Cloudflare Workers and Vercel:

     POST /api/licenses/webhook   Stripe calls this when someone pays. It checks the
                         call really came from Stripe, reads the payment back
                         from Stripe, makes the license key and emails it to
                         the address the buyer gave at checkout.
     POST /api/licenses/redeem    activate.html on the static site calls this with the
                         checkout reference Stripe sent the buyer back with,
                         and shows the key on screen as well.
     GET  /api/licenses/health which settings are present (names only, never values).

   Settings (the host's environment; real values never go in the repository):
     STRIPE_RESTRICTED_KEY   a Stripe key that can only READ checkout sessions and subscriptions
     STRIPE_WEBHOOK_SECRET   whsec_..., from the webhook endpoint's page in Stripe
     STRIPE_PRICE_MONTHLY, STRIPE_PRICE_ANNUAL   the two price ids
     LICENSE_SIGNING_KEY     the private key (PEM) that signs license keys
     RESEND_API_KEY          the email service's key
     EMAIL_FROM              for example  Cognicopia <licenses@cognicopia.org>
     EMAIL_REPLY_TO          optional, for example cognicopia@outlook.com
     SITE_URL                default https://cognicopia.org
     LICENSE_ALLOWED_ORIGINS default https://cognicopia.org (comma separated)
   A missing setting breaks only what needs it, and the answer names the setting, never a value.
   ===================================================================== */



const SETTINGS = ["STRIPE_RESTRICTED_KEY", "STRIPE_WEBHOOK_SECRET", "STRIPE_PRICE_MONTHLY", "STRIPE_PRICE_ANNUAL", "LICENSE_SIGNING_KEY", "RESEND_API_KEY", "EMAIL_FROM"];
const json = (status, body, headers = {}) => new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json", "Cache-Control": "no-store", ...headers } });
const problem = (status, code, message, headers) => json(status, { error: { code, message } }, headers);
const get = (env, name) => (env && typeof env[name] === "string" ? env[name].trim() : "");

/** Throws a 503 that names the missing setting. */
function need(env, ...names) {
  const out = {};
  for (const n of names) {
    out[n] = get(env, n);
    if (!out[n]) throw new ServiceError(503, "not_set_up", `This service is not set up yet: ${n} is missing.`);
  }
  return out;
}
const prices = (env) => ({ monthly: get(env, "STRIPE_PRICE_MONTHLY"), annual: get(env, "STRIPE_PRICE_ANNUAL") });
const siteUrl = (env) => get(env, "SITE_URL") || "https://cognicopia.org";
const origins = (env) => (get(env, "LICENSE_ALLOWED_ORIGINS") || "https://cognicopia.org").split(",").map((s) => s.trim()).filter(Boolean);

function fail(error) {
  if (error instanceof ServiceError || (error && typeof error.status === "number" && typeof error.code === "string")) return problem(error.status, error.code, error.message);
  console.error("license-service: unexpected error");                    // no detail: a message could carry a value
  return problem(500, "server_error", "Something went wrong on our side.");
}

/* ---------- /api/licenses/redeem ---------- */
const hits = new Map();
function takeTry(key, now = Date.now(), limit = 10, windowMs = 60_000) {
  const recent = (hits.get(key) ?? []).filter((t) => now - t < windowMs);
  if (recent.length >= limit) { hits.set(key, recent); return false; }
  recent.push(now); hits.set(key, recent);
  if (hits.size > 5000) for (const [k, list] of hits) if (list.every((t) => now - t >= windowMs)) hits.delete(k);
  return true;
}
const clientAddress = (request) => (request.headers.get("x-nf-client-connection-ip") || request.headers.get("cf-connecting-ip") || (request.headers.get("x-forwarded-for") || "").split(",")[0].trim() || "unknown");
const cors = (origin, allowed) => (origin && allowed.includes(origin)
  ? { "Access-Control-Allow-Origin": origin, "Access-Control-Allow-Methods": "POST, OPTIONS", "Access-Control-Allow-Headers": "Content-Type", "Access-Control-Max-Age": "600", Vary: "Origin" }
  : { Vary: "Origin" });

async function handleRedeem(request, env, deps = {}) {
  try {
    const allowed = origins(env), origin = request.headers.get("origin"), headers = cors(origin, allowed);
    if (request.method === "OPTIONS") return new Response(null, { status: headers["Access-Control-Allow-Origin"] ? 204 : 403, headers });
    if (request.method !== "POST") return problem(405, "method_not_allowed", "Use POST.", headers);
    if (origin && !headers["Access-Control-Allow-Origin"]) return problem(403, "forbidden_origin", "This request came from a site that may not use it.", headers);
    if (!takeTry(clientAddress(request), deps.now?.().getTime?.())) return problem(429, "rate_limited", "Too many tries. Please wait a few minutes.", headers);
    let body = null;
    try { body = await request.json(); } catch { /* handled below */ }
    const reference = body && typeof body.session_id === "string" ? body.session_id : "";
    if (!reference || reference.length > 300) return problem(422, "invalid", "Send the checkout reference as session_id.", headers);
    const s = need(env, "STRIPE_RESTRICTED_KEY", "STRIPE_PRICE_MONTHLY", "STRIPE_PRICE_ANNUAL", "LICENSE_SIGNING_KEY");
    const done = await redeemCheckout({ stripeKey: s.STRIPE_RESTRICTED_KEY, signingKey: s.LICENSE_SIGNING_KEY, prices: prices(env), fetch: deps.fetch, now: deps.now }, reference);
    return json(200, { license_key: done.licenseKey, facility_name: done.facilityName, tier: done.tier, expires_at: done.expiresAt }, headers);
  } catch (error) {
    return fail(error);
  }
}

/* ---------- /api/licenses/webhook ---------- */
const PAID_EVENTS = new Set(["checkout.session.completed", "checkout.session.async_payment_succeeded"]);

async function handleWebhook(request, env, deps = {}) {
  try {
    if (request.method !== "POST") return problem(405, "method_not_allowed", "Use POST.");
    const s = need(env, "STRIPE_WEBHOOK_SECRET", "STRIPE_RESTRICTED_KEY", "STRIPE_PRICE_MONTHLY", "STRIPE_PRICE_ANNUAL", "LICENSE_SIGNING_KEY", "RESEND_API_KEY", "EMAIL_FROM");
    const raw = await request.text();
    const now = deps.now ? deps.now().getTime() : Date.now();
    if (!(await verifyStripeSignature(raw, request.headers.get("stripe-signature"), s.STRIPE_WEBHOOK_SECRET, { now }))) {
      return problem(400, "bad_signature", "That did not come from Stripe.");
    }
    let event;
    try { event = JSON.parse(raw); } catch { return problem(400, "bad_json", "That is not a Stripe event."); }
    if (!event || !PAID_EVENTS.has(event.type)) return json(200, { received: true, ignored: true });

    const id = event.data?.object?.id;
    if (typeof id !== "string" || !CHECKOUT_REFERENCE.test(id)) return json(200, { received: true, ignored: true });

    // The event only says WHICH session. What it is, and whether it is paid, is read back from Stripe.
    const session = await retrieveCheckoutSession(id, s.STRIPE_RESTRICTED_KEY, deps.fetch);
    let license;
    try {
      license = await licenseFromSession({ signingKey: s.LICENSE_SIGNING_KEY, prices: prices(env), now: deps.now }, session);
    } catch (error) {
      if (error instanceof ServiceError && (error.code === "not_a_license" || (error.code === "not_paid" && session.payment_status === "unpaid"))) {
        return json(200, { received: true, ignored: true });                // another product, or a bank payment that has not cleared yet (a later event follows)
      }
      throw error;
    }
    const to = session.customer_details?.email || session.customer_email || "";
    if (!to || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)) {
      console.error(`license-service: ${id} has no email address to send the key to`);
      return json(200, { received: true, delivered: false, reason: "no_email" });
    }
    const message = licenseEmail({ ...license, siteUrl: siteUrl(env) });
    await sendEmail({ apiKey: s.RESEND_API_KEY, from: s.EMAIL_FROM, replyTo: get(env, "EMAIL_REPLY_TO") || undefined, to, ...message, idempotencyKey: `license-${id}` }, deps.fetch);
    console.log(`license-service: sent the license for ${id}`);
    return json(200, { received: true, delivered: true });
  } catch (error) {
    return fail(error);
  }
}

/* ---------- /api/licenses/health ---------- */
function handleHealth(env) {
  const settings = {};
  for (const n of SETTINGS) settings[n] = !!get(env, n);
  return json(200, { ok: true, ready: Object.values(settings).every(Boolean), settings });
}

/** One entry for hosts that give a service a single function (Cloudflare Workers, a plain Node server). */
async function route(request, env, deps) {
  const path = new URL(request.url).pathname.replace(/\/+$/, "");
  if (path.endsWith("/api/licenses/webhook")) return handleWebhook(request, env, deps);
  if (path.endsWith("/api/licenses/redeem")) return handleRedeem(request, env, deps);
  if (path.endsWith("/api/licenses/health")) return handleHealth(env);
  return problem(404, "not_found", "Nothing is here.");
}

export default { fetch: (request, env) => route(request, env) };
